-- Read-only prerequisite catalog. Compare the exact result with the tested snapshot.
select jsonb_build_object(
 'functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'md5',md5(pg_get_functiondef(p.oid)),'definition',pg_get_functiondef(p.oid),'acl',p.proacl::text) order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='public' and p.proname in ('update_comment_count','sync_post_comment_count','sync_post_comments_count','triniti_admin_session_check','triniti_platinum_admin_command','triniti_admin_provision','triniti_admin_deletion_requests')) or (n.nspname='admin_ops' and p.proname='require_session')),
 'admin_relations',(select jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'acl',c.relacl::text) order by c.relname) from pg_class c where c.relnamespace=to_regnamespace('admin_ops') and c.relkind='r'),
 'guard_triggers',coalesce((select jsonb_agg(jsonb_build_object('table',t.tgrelid::regclass::text,'name',t.tgname,'definition',pg_get_triggerdef(t.oid)) order by t.tgname) from pg_trigger t where not t.tgisinternal and t.tgname in ('capture_admin_removal','admin_removed_post_guard','admin_removed_story_guard','admin_removed_comment_guard','admin_removed_listing_guard','guard_profile_verification','guard_verification_application','sync_verification_revocation')),'[]'::jsonb),
 'columns',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull) order by c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid where c.relnamespace='public'::regnamespace and c.relname in ('admin_users','admin_audit_log','profiles','verification_applications','user_reports','post_reports','listing_reports','support_tickets','support_messages','business_applications','business_members','organizations','org_memberships','org_delegations','org_audit_log','studio_campaigns','member_strikes','feature_flags','announcements','blocked_words') and a.attnum>0 and not a.attisdropped),
 'verification_constraint',(select jsonb_agg(pg_get_constraintdef(oid)) from pg_constraint where conrelid='public.verification_applications'::regclass and contype='c'),
 'policies',(select jsonb_agg(to_jsonb(p) order by tablename,policyname) from pg_policies p where schemaname='public' and tablename in ('verification_applications','user_reports','admin_users','admin_audit_log'))
) preflight;
